import { describe, expect, test } from "vitest";
import { components, generate } from "../scripts/tailwind-files.ts";

// src/tailwind/ is generated by scripts/build-tailwind.ts and checked in; it must be current.

const sources = import.meta.glob<string>(
  ["../src/components/*/*.{ts,tsx}", "../src/core/**/*.{ts,tsx}", "../src/tailwind-src/*.ts"],
  { query: "?raw", import: "default", eager: true },
);
const written = import.meta.glob<string>("../src/tailwind/**/*.{ts,tsx}", {
  query: "?raw",
  import: "default",
  eager: true,
});

const under = (files: Record<string, string>, prefix: string) =>
  Object.fromEntries(
    Object.entries(files).map(([path, code]) => [path.slice(prefix.length), code]),
  );

describe("src/tailwind (generated)", () => {
  const expected = generate(under(sources, "../src/"));
  const actual = under(written, "../src/tailwind/");

  test("holds the same files as the generator makes", () => {
    expect(Object.keys(actual).sort()).toEqual(Object.keys(expected).sort());
  });

  test("is current: run `pnpm --filter owsem-ui tailwind:build` after changing a source", () => {
    for (const [path, code] of Object.entries(expected)) {
      expect(actual[path], path).toBe(code);
    }
  });

  test("starts every file with the generated header and imports no CSS", () => {
    for (const [path, code] of Object.entries(actual)) {
      expect(code.startsWith("// Generated from "), path).toBe(true);
      expect(code, path).not.toMatch(/\.css["']/);
    }
  });

  test("makes a folder for every listed component, with its variants file swapped in", () => {
    for (const name of components) {
      expect(actual[`${name}/${name}-variants.ts`], name).toContain("The Tailwind CSS v4 twin of");
      expect(
        Object.keys(actual).filter((path) => path.startsWith(`${name}/`)),
        name,
      ).toContain(`${name}/index.ts`);
    }
  });

  test("copies the core modules a component needs, and the ones those need", () => {
    expect(
      Object.keys(actual)
        .filter((path) => path.startsWith("lib/"))
        .sort(),
    ).toEqual([
      "lib/checkbox-group-size.ts",
      "lib/cn.ts",
      "lib/glide/glide-variants.ts",
      "lib/glide/glide.ts",
      "lib/glide/use-glide.tsx",
      "lib/merge-refs.ts",
      "lib/resting-anchor.ts",
      "lib/scroll-lock.ts",
      "lib/shake.ts",
      "lib/use-ripple.ts",
    ]);
    expect(actual["lib/shake.ts"]).toContain('from "./merge-refs"');
    expect(actual["lib/resting-anchor.ts"]).toContain('from "./merge-refs"');
    expect(actual["input/input.tsx"]).toContain('from "../lib/shake"');
  });

  test("a component that uses another resolves to its Tailwind flavor", () => {
    expect(actual["field/field.parts.ts"]).toContain('from "../input/input"');
    expect(components).toContain("input");
  });

  test("nested core modules go to lib/ with their folder, and their siblings and parents resolve", () => {
    expect(actual["radio-group/radio-group.tsx"]).toContain('from "../lib/glide/use-glide"');
    expect(actual["radio-group/radio-group.tsx"]).toContain('from "../lib/glide/glide"');
    const hook = actual["lib/glide/use-glide.tsx"] ?? "";
    expect(hook).toContain('from "./glide"');
    expect(hook).toContain('from "./glide-variants"');
    expect(hook).toContain('from "../cn"');
    expect(hook).not.toContain(".css");
  });

  test("a core module's Tailwind twin replaces the plain file, .ts or .tsx alike", () => {
    expect(actual["lib/glide/glide-variants.ts"]).toContain("The Tailwind CSS v4 twin of");
    expect(actual["lib/glide/glide-variants.ts"]).toContain(
      "// Generated from core/glide/glide-variants.tailwind.ts",
    );
    const all = under(sources, "../src/");
    all["core/glide/glide-variants.tailwind.ts"] = "export const twin = 1;\n";
    all["core/extra.tsx"] = 'export const extra = "x";\n';
    all["components/kbd/kbd.tsx"] =
      `import { extra } from "../../core/extra";\n${all["components/kbd/kbd.tsx"]}`;
    const made = generate(all);
    expect(made["lib/glide/glide-variants.ts"]).toContain("twin");
    expect(made["lib/extra.tsx"]).toContain('"x"');
    expect(made["kbd/kbd.tsx"]).toContain('from "../lib/extra"');
  });

  test("toggle-group's thumb.ts resolves for tabs", () => {
    expect(actual["toggle-group/thumb.ts"]).toBeDefined();
    expect(actual["tabs/tabs.tsx"]).toContain('from "../toggle-group/thumb"');
    expect(components.indexOf("toggle-group")).toBeLessThan(components.indexOf("tabs"));
  });

  test("a component that uses one without a Tailwind flavor fails, naming it", () => {
    const code = 'export { GhostRoot as Control } from "../ghost/ghost";\n';
    const withGhost = { ...under(sources, "../src/"), "components/field/field.parts.ts": code };
    expect(() => generate(withGhost)).toThrow(
      /field\/field\.parts\.ts: imports ghost, which has no Tailwind flavor/,
    );
  });

  test("every component folder is listed, so each has a Tailwind flavor", () => {
    const folders = new Set(
      Object.keys(sources)
        .map((path) => /^\.\.\/src\/components\/([^/]+)\//.exec(path)?.[1])
        .filter((name): name is string => !!name),
    );
    expect([...folders].sort()).toEqual([...components].sort());
    expect(folders.size).toBe(38);
  });

  test("a listed component without a Tailwind variants file fails, naming it", () => {
    const all = under(sources, "../src/");
    delete all["components/kbd/kbd-variants.tailwind.ts"];
    expect(() => generate(all)).toThrow(
      /Missing source: components\/kbd\/kbd-variants\.tailwind\.ts/,
    );
  });

  test("a core module that does not exist fails, naming it", () => {
    const all = under(sources, "../src/");
    all["components/kbd/kbd.tsx"] =
      `import "../../core/nothing";\n${all["components/kbd/kbd.tsx"]}`;
    expect(() => generate(all)).toThrow(/kbd\/kbd\.tsx: core\/nothing is not a module/);
  });
});
